__NUXT_JSONP__("/de/firstday-at-mli", (function(a,b){return {data:[{details:{slug:"de",pageTitle:"Der erste Tag am MLI | Mentor Language Institute",pageDescription:a,title:"Der erste Tag am MLI",image:"\u002Fimages\u002Fwhat-is-mli\u002Ffirst-day-at-mli\u002Fmli-signup.jpg",categories:[{title:"Willkommen beim Mentor Language Institute!",description:[a,"Die Orientierung liefert dir wichtige Informationen zum besseren Verständnis unserer Programme, den Einwanderungsbestimmungen und Schulregeln. Du wirst von unserem Studiensekretariat, von unseren Lehrern, der Rezeption, dem Verwaltungs- und dem Managementpersonal begrüsst."],dates:["＜Anfangsdatum der einzelnen Semester＞","- May 22nd, 2023 \u003Cbr\u002F\u003E - June 20th, 2023 \u003Cbr\u002F\u003E - July 17th, 2023 \u003Cbr\u002F\u003E - August 14th, 2023 \u003Cbr\u002F\u003E - September 11th, 2023 \u003Cbr\u002F\u003E - October 10th, 2023 \u003Cbr\u002F\u003E - November 6th, 2023 \u003Cbr\u002F\u003E - December 4th, 2023 \u003Cbr\u002F\u003E - January 8th, 2024 \u003Cbr\u002F\u003E - February 5th, 2024 \u003Cbr\u002F\u003E - March 4th, 2024","Die Orientierung startet um 13:00 Uhr."],groups:[{title:"Orientierungs- und Einstufungstest",listType:"table",lists:[{key:"13:00 – 13:30Uhr",value:"Anmeldeunterlagen"},{key:"13:30 – 14:00Uhr",value:"Akademische Orientierung"},{key:"14:00 – 15:00Uhr",value:"Einstufungstest"},{key:"15:15 – 15:35Uhr",value:"Schulrichtlinien, Immigrationsregeln"},{key:"15:35 – 15:50Uhr",value:"College Transfer Service"},{key:"15:50 – 16:00Uhr",value:"Aktivitäten & Wohnen"},{key:"16:00 – 16:10Uhr",value:"mündlicher Test & Klassenzuweisung"},{key:"16:10 – 16:20Uhr",value:b}]},{title:"Was du am ersten Tag mitbringen musst",lists:["Pass (Als u houder bent van een studentenvisum)","I-20 (Als u houder bent van een studentenvisum)","Stift und Papier","Leerboekgeld en collegegeldbetaling"]}]},{title:"Details",groups:[{title:"Orientierungsplan",description:["Zuerst füllst du die notwendigen Unterlagen für die Einschreibung aus.\u003Cbr \u002F\u003EAls nächstes wird der Akademische Direktor oder der Programmkoordinator eine Präsentation über unsere verschiedenen Programme, die Klassenregeln und wie du erfolgreich von einem Level in das nächsthöhere wechselst, halten."]},{title:"Einstufungstest und Interview",description:["Nach der Orientierung folgt der \"\"Englisch Einstufungstest\"\" mit etwa 80 Fragen. Er umfasst einen Hör- und Schreibteil, welcher Grammatik, Wortschatz und Leseverständnis behandelt. Es ist ein 60-minütiger Test, der dein Englischlevel bestimmt.\u003Cbr \u002F\u003ENach dem Test gibt es einen kurzen mündlichen Test (mehr wie ein Interview) mit einem unserer Instruktoren (entweder der Programmkoordinator, der Akademische Direktor oder ein MLI Lehrer).\u003Cbr \u002F\u003EDieser Test soll dabei helfen das richtige Level und\u002Foder Programm für dich zu finden, basierend auf deinem jetzigen Wissenstand und deinen Zielen."]},{title:b,description:["Nach dem Einstufungstest und dem Interview kaufen die Schüler ihre Lehrbücher an der Rezeption. Die Mitarbeiter der Rezeption stehen dir gerne zur Verfügung, um weitere Fragen oder Anliegen zu beantworten."]}]}],dir:"\u002Ffirstday-at-mli",path:"\u002Ffirstday-at-mli\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:29.257Z",updatedAt:"2025-05-26T12:06:27.755Z"}}],fetch:{},mutations:void 0}}("Am MLI haben wir eine Orientierungsveranstaltung für neue Studenten zu Beginn jedes Semesters (alle 4 Wochen).","Lehrbücher kaufen")));